import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var result = 0
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result
    }
}

private fun countInvalid(side: Int, other1: Int, other2: Int, limit: Int): Long {
    var result = 0L
    val required = other1 + other2 - side

    for (sumOthers in 0..limit) {
        val minIncrease = maxOf(0, sumOthers + required)
        val maxIncrease = limit - sumOthers

        if (minIncrease <= maxIncrease) {
            val otherWays = sumOthers.toLong() + 1L
            val sideWays = (maxIncrease - minIncrease + 1).toLong()
            result += otherWays * sideWays
        }
    }
    return result
}

fun main() {
    val fs = FastScanner()
    val a = fs.nextInt()
    val b = fs.nextInt()
    val c = fs.nextInt()
    val l = fs.nextInt()

    val total = (l + 1L) * (l + 2L) * (l + 3L) / 6L

    val invalid = countInvalid(a, b, c, l) +
            countInvalid(b, a, c, l) +
            countInvalid(c, a, b, l)

    print(total - invalid)
}

