import java.io.BufferedInputStream

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var value = 0
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return value
    }
}

private fun countInvalid(longSide: Int, side1: Int, side2: Int, limit: Int): Long {
    val requiredDifference = side1 + side2 - longSide
    var result = 0L

    for (sumOtherIncrements in 0..limit) {
        val minimumLongIncrement = maxOf(0, requiredDifference + sumOtherIncrements)
        val maximumLongIncrement = limit - sumOtherIncrements

        if (minimumLongIncrement <= maximumLongIncrement) {
            val pairs = sumOtherIncrements.toLong() + 1L
            val choices = (maximumLongIncrement - minimumLongIncrement + 1).toLong()
            result += pairs * choices
        }
    }

    return result
}

fun main() {
    val fs = FastScanner()
    val a = fs.nextInt()
    val b = fs.nextInt()
    val c = fs.nextInt()
    val l = fs.nextInt()

    val n = l.toLong()
    val totalWays = (n + 1L) * (n + 2L) * (n + 3L) / 6L

    val invalidWays =
        countInvalid(a, b, c, l) +
        countInvalid(b, a, c, l) +
        countInvalid(c, a, b, l)

    print(totalWays - invalidWays)
}
